-- THE STATE JOURNAL (Michael 2026-11-07: "GROWTH is just a giant log of history"; nothing is overwritten, the current state is a view).
-- Every insert, change and delete of a world row is journaled by SQLite itself, inside the same transaction, whatever code path made it.
-- `row` = the row as it was BEFORE an update/delete, or as inserted. `cycle` = the campaign clock at that moment.
CREATE TABLE "StateJournal" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "at" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "campaignId" TEXT, "cycle" REAL, "tableName" TEXT NOT NULL, "rowId" TEXT NOT NULL, "op" TEXT NOT NULL, "row" TEXT NOT NULL, "changed" TEXT);
CREATE INDEX "StateJournal_tableName_rowId_idx" ON "StateJournal"("tableName", "rowId");
CREATE INDEX "StateJournal_campaignId_cycle_idx" ON "StateJournal"("campaignId", "cycle");
CREATE TRIGGER "journal_Character_update" AFTER UPDATE ON "Character" WHEN OLD."name" IS NOT NEW."name" OR OLD."entityType" IS NOT NEW."entityType" OR OLD."userId" IS NOT NEW."userId" OR OLD."data" IS NOT NEW."data" OR OLD."portrait" IS NOT NEW."portrait" OR OLD."status" IS NOT NEW."status" OR OLD."genesisTier" IS NOT NEW."genesisTier" BEGIN INSERT INTO "StateJournal" ("campaignId", "cycle", "tableName", "rowId", "op", "row", "changed") VALUES (OLD."campaignId", (SELECT "currentCycle" FROM "Campaign" WHERE "id" = OLD."campaignId"), 'Character', OLD.id, 'update', json_object('id', OLD.id, 'name', OLD."name", 'entityType', OLD."entityType", 'userId', OLD."userId", 'data', OLD."data", 'portrait', OLD."portrait", 'status', OLD."status", 'genesisTier', OLD."genesisTier"), json_array(CASE WHEN OLD."name" IS NOT NEW."name" THEN 'name' END, CASE WHEN OLD."entityType" IS NOT NEW."entityType" THEN 'entityType' END, CASE WHEN OLD."userId" IS NOT NEW."userId" THEN 'userId' END, CASE WHEN OLD."data" IS NOT NEW."data" THEN 'data' END, CASE WHEN OLD."portrait" IS NOT NEW."portrait" THEN 'portrait' END, CASE WHEN OLD."status" IS NOT NEW."status" THEN 'status' END, CASE WHEN OLD."genesisTier" IS NOT NEW."genesisTier" THEN 'genesisTier' END)); END;
CREATE TRIGGER "journal_Character_delete" AFTER DELETE ON "Character" BEGIN INSERT INTO "StateJournal" ("campaignId", "cycle", "tableName", "rowId", "op", "row") VALUES (OLD."campaignId", (SELECT "currentCycle" FROM "Campaign" WHERE "id" = OLD."campaignId"), 'Character', OLD.id, 'delete', json_object('id', OLD.id, 'name', OLD."name", 'entityType', OLD."entityType", 'userId', OLD."userId", 'data', OLD."data", 'portrait', OLD."portrait", 'status', OLD."status", 'genesisTier', OLD."genesisTier")); END;
CREATE TRIGGER "journal_Character_insert" AFTER INSERT ON "Character" BEGIN INSERT INTO "StateJournal" ("campaignId", "cycle", "tableName", "rowId", "op", "row") VALUES (NEW."campaignId", (SELECT "currentCycle" FROM "Campaign" WHERE "id" = NEW."campaignId"), 'Character', NEW.id, 'insert', json_object('id', NEW.id, 'name', NEW."name", 'entityType', NEW."entityType", 'userId', NEW."userId", 'data', NEW."data", 'portrait', NEW."portrait", 'status', NEW."status", 'genesisTier', NEW."genesisTier")); END;
