CREATE TRIGGER "journal_CampaignItem_insert" AFTER INSERT ON "CampaignItem" BEGIN INSERT INTO "StateJournal" ("campaignId", "cycle", "tableName", "rowId", "op", "row") VALUES (NEW."campaignId", (SELECT "currentCycle" FROM "Campaign" WHERE "id" = NEW."campaignId"), 'CampaignItem', NEW.id, 'insert', json_object('id', NEW.id, 'name', NEW."name", 'type', NEW."type", 'data', NEW."data", 'holderId', NEW."holderId", 'locationId', NEW."locationId", 'status', NEW."status", 'story', NEW."story", 'history', NEW."history")); END;
